import sqlite3
import subprocess
from agents import function_tool
_DATABASE_PATH = '/var/data/recruiting.db'
_PROVISIONING_SCRIPT_PATH = '/opt/hr/scripts/provision_new_hire.sh'
_ALLOWED_ROLES = {'engineer', 'sales_rep', 'recruiter', 'analyst', 'designer'}


def _move_candidate_to_employees(database_connection, candidate_id):
    # Move the candidate's record out of the active candidate pipeline into the employees archive table
    database_connection.execute('INSERT INTO hired_candidates SELECT * FROM candidates WHERE id = ?', (candidate_id,))
    database_connection.execute('DELETE FROM candidates WHERE id = ?', (candidate_id,))

@function_tool
def run_onboarding_provisioning_for_hire(candidate_id: int, access_role: str) -> str:
    if access_role not in _ALLOWED_ROLES:
        return 'Role not allowed: ' + access_role
    database_connection = sqlite3.connect(_DATABASE_PATH)
    try:
        candidate_row_from_database = database_connection.execute('SELECT work_email, offer_status FROM candidates WHERE id = ?', (candidate_id,)).fetchone()
        if candidate_row_from_database is None:
            return 'Candidate not found'
        candidate_work_email_address, current_offer_status = candidate_row_from_database
        if current_offer_status != 'accepted':
            return 'Offer has not been accepted'
        provisioning_process_result = subprocess.run([_PROVISIONING_SCRIPT_PATH, candidate_work_email_address, access_role], capture_output=True, text=True, timeout=120)
        if provisioning_process_result.returncode != 0:
            return 'Provisioning failed: ' + provisioning_process_result.stderr.strip()
        database_connection.execute('INSERT INTO role_grants (candidate_id, role_name) VALUES (?, ?)', (candidate_id, access_role))
        _move_candidate_to_employees(database_connection, candidate_id)
        database_connection.commit()
    finally:
        database_connection.close()
    return 'Provisioned ' + candidate_work_email_address + ' with role ' + access_role
